const form=document.getElementById("maternityForm"),result=document.getElementById("result"),mode=document.getElementById("mode"),daysField=document.getElementById("daysField"),minCareField=document.getElementById("minCareField"),daysEl=document.getElementById("days"),minCareEl=document.getElementById("minCare");function toggle(){mode&&mode.value==="care"?(daysField.style.display="none",minCareField.style.display="",daysEl.required=!1,minCareEl.required=!0):(daysField.style.display="",minCareField.style.display="none",daysEl.required=!0,minCareEl.required=!1)}mode&&(mode.addEventListener("change",toggle),toggle()),form&&form.addEventListener("submit",s=>{s.preventDefault();const n=parseFloat(document.getElementById("income").value)||0,t=parseFloat(document.getElementById("mrot").value)||22440,d=mode&&mode.value,l=parseInt(daysEl.value,10)||140,i=parseFloat(minCareEl.value)||10103;if(n<=0||t<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите доход и МРОТ больше нуля.</p>';return}const a=Math.max(n/730,t*24/730);if(d==="care"){const e=a*30.4,c=Math.max(e*.4,i);result.innerHTML=`
        <div class="result-list">
          <div class="item"><span>Средний дневной</span><span class="val">${fmt(a)} ₽</span></div>
          <div class="item"><span>Средний месячный</span><span class="val">${fmt(e)} ₽</span></div>
          <div class="item"><span>40% от среднего</span><span class="val">${fmt(e*.4)} ₽</span></div>
          <div class="item total"><span>Пособие в месяц (не менее ${fmt(i)} ₽)</span><span class="val">${fmt(c)} ₽</span></div>
        </div>
      `}else{const e=a*l;result.innerHTML=`
        <div class="result-list">
          <div class="item"><span>Средний дневной</span><span class="val">${fmt(a)} ₽</span></div>
          <div class="item"><span>Дней отпуска</span><span class="val">${l}</span></div>
          <div class="item total"><span>Пособие за отпуск</span><span class="val">${fmt(e)} ₽</span></div>
        </div>
      `}});function fmt(s){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(s)}
